// Generated by `npm run extract` from your installed Minecraft jar (git-ignored).
import raw from './blocks.json';
import type { BlockData } from '../core/types';

export const blockData = raw as unknown as BlockData;
export const BLOCKS = blockData.blocks;
export const blockIndexById = new Map(BLOCKS.map((b, i) => [b.id, i]));
export const ATLAS_URL = `${import.meta.env.BASE_URL}atlas.png`;

export const DEFAULT_CATEGORIES = ['Concrete', 'Wool', 'Terracotta'];
export const defaultEnabledIds = (): string[] =>
  BLOCKS.filter((b) => DEFAULT_CATEGORIES.includes(b.category)).map((b) => b.id);
